import re
import os
from taf.internal.managedobject import ManagedObject
from taf.ul.mobile.ui.android.exceptions import DumpUIXmlFailed, GetUIXmlFailed, GetAdbOutputFailed


class AdbProxy(ManagedObject):

    def __init__(self, executor, serial_number="", **kwargs):
        super(AdbProxy, self).__init__(**kwargs)
        self._executor = executor
        self._serial_number = serial_number
        self.add_prerequisite(self._executor)

    def get_brand(self):
        return self._executor.execute(
            self._construct_command("adb shell getprop ro.product.brand")).split(" \r\n")[0].replace(" ", "")

    def get_model(self):
        return self._executor.execute(
            self._construct_command("adb shell getprop ro.product.model")).split(" \r\n")[0].replace(" ", "")

    def get_android_version(self):
        return self._executor.execute(
            self._construct_command("adb shell getprop ro.build.version.release")).split(" \r\n")[0].replace(" ", "")

    def get_sim_operator_alpha(self):
        adb_command = "adb shell getprop gsm.sim.operator.alpha"
        output = self._executor.execute(self._construct_command(adb_command))
        output_lines = [line.strip() for line in output.splitlines() if line.strip()]
        if not output_lines:
            raise GetAdbOutputFailed(adb_command)
        return output_lines[-1]

    def get_windows_size(self):
        windows_size_info = self._executor.execute(
            self._construct_command("adb shell wm size"))

        x, y = re.search(r"(\d+)x(\d+)", windows_size_info).groups()
        return (int(x), int(y))

    def wipe_screen(self, from_position, to_position):
        self._executor.execute(
            self._construct_command("adb shell input swipe {} {} {} {}".format(*(from_position + to_position))))

    def tap_by_postion(self, postion):
        self._executor.execute(
            self._construct_command("adb shell input tap {} {}".format(*postion)))

    def input_text(self, text):
        self._executor.execute(
            self._construct_command("adb shell input text {}".format(text)))

    def dump_ui_xml(self, to_file_path="", try_times=3):
        to_file_path = to_file_path if to_file_path else "/sdcard/windows_dump.xml"
        file_name = os.path.basename(to_file_path)
        dir_path = os.path.dirname(to_file_path)

        self._executor.execute(
            self._construct_command("adb shell rm {}".format(to_file_path)))

        while try_times:
            self._executor.execute(
                self._construct_command("adb shell uiautomator dump {}".format(to_file_path)))
            output = self._executor.execute(
                self._construct_command("adb shell ls {}".format(dir_path)))
            if file_name in output:
                return to_file_path

            try_times -= 1

        raise DumpUIXmlFailed("adb dump xml file {} failed".format(to_file_path))

    def pull_file_from_ue_to_local(self, ue_file_path, local_file_path):
        self._executor.execute(
            self._construct_command("adb pull {} {}".format(ue_file_path, local_file_path)))

    def get_ui_xml_content(self, try_times=3):
        ui_xml_file = self.dump_ui_xml()
        while try_times:
            content = self._executor.execute(
                self._construct_command("adb shell cat {}".format(ui_xml_file))).replace("\r\n", "").strip()
            if content:
                return content
            try_times -= 1
        raise GetUIXmlFailed

    def force_stop_setting(self):
        self._executor.execute(
            self._construct_command("adb shell am force-stop com.android.settings"))

    def input_home_key(self):
        self._executor.execute(
            self._construct_command("adb shell input keyevent 3"))

    def input_delete_key(self):
        self._executor.execute(
            self._construct_command("adb shell input keyevent 67"))

    def input_forward_delete_key(self):
        self._executor.execute(
            self._construct_command("adb shell input keyevent 112"))

    def input_return_key(self):
        self._executor.execute(
            self._construct_command("adb shell input keyevent 4"))

    def input_space(self):
        self._executor.execute(
            self._construct_command("adb shell input keyevent 62"))

    def input_power_key(self):
        self._executor.execute(
            self._construct_command("adb shell input keyevent 26"))

    def input_menu_key(self):
        self._executor.execute(
            self._construct_command("adb shell input keyevent 82"))

    def open_setting(self):
        self._executor.execute(
            self._construct_command("adb shell am start -a android.settings.SETTINGS"))

    def is_sim_card_active_for_slot_index(self, slot_index):
        raise NotImplementedError

    def get_default_mobile_data_slot_index(self):
        sub_id = self._get_default_data_sub_id()
        return self._get_slot_index_by_sub_id(sub_id)

    def _get_default_data_sub_id(self):
        raise NotImplementedError

    def _get_slot_index_by_sub_id(self, sub_id):
        raise NotImplementedError

    def enable_airplane_mode(self):
        self._executor.execute(
            self._construct_command("adb shell settings put global airplane_mode_on 1"), timeout=2)

    def disable_airplane_mode(self):
        self._executor.execute(
            self._construct_command("adb shell settings put global airplane_mode_on 0"), timeout=2)

    def force_stop_dail(self):
        self._executor.execute(
            self._construct_command("adb shell am force-stop com.android.dialer"))

    def start_dail(self):
        self._executor.execute(
            self._construct_command("adb shell am start -a android.intent.action.DIAL"))

    def return_to_parentlevel(self):
        self._executor.execute(
            self._construct_command("adb shell input keyevent 4"))

    def start_dial_with_number(self, number):
        self._executor.execute(
            self._construct_command("adb shell am start -a android.intent.action.DIAL -d tel:{}".format(number)))

    def _construct_command(self, command):
        if not self._serial_number:
            return command
        return command.replace("adb", "adb -s {}".format(self._serial_number))

    def start_app_activity(self, app_activity):
        return self._executor.execute(
            self._construct_command("adb shell am start {}".format(app_activity)))

    def stop_app_activity(self, app_activity):
        return self._executor.execute(
            self._construct_command("adb shell am force-stop {}".format(app_activity)))

    def get_ip_config_report(self):
        return self._executor.execute(
            self._construct_command("adb shell ip -f inet addr"))

    def dump_system_windows_display(self):
        return self._executor.execute(
            self._construct_command('adb shell dumpsys window'))

    def is_screen_locked(self):
        output = self.dump_system_windows_display()

        if 'mAwake=false' in output or 'isStatusBarKeyguard=true' in output or 'mShowingLockScreen=true' in output:
            return True
        return False

    def unlock_screen(self):
        output = self.dump_system_windows_display()
        if 'mAwake=false' in output:
            self.input_power_key()
        self.input_menu_key()

    def enable_mobile_data(self):
        return self._executor.execute(
            self._construct_command('adb shell svc data enable'))

    def disable_mobile_data(self):
        return self._executor.execute(
            self._construct_command('adb shell svc data disable'))
